--- index.html
+++ index.html
@@ -23,4 +23,32 @@
 </section>
 <footer class="footer"><span>AN ARCADE FLIGHT SIMULATION <b>·</b> FICTIONAL THEATER</span><span>BUILD 01.08 <b>·</b> SKYWARD AERONAUTICS</span></footer>
 </main>
 <script>
+(()=>{
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
+const $=s=>document.querySelector(s), screen=$('#screen'), card=$('#screenCard');
+const weapons=[
+ {id:'standard',name:'STANDARD',label:'Standard payload',cost:0,unlock:1,count:3,radius:43,color:'#ffd16a',desc:'Reliable single-target blast.'},
+ {id:'cluster',name:'CLUSTER',label:'Cluster payload',cost:100,unlock:2,count:2,radius:78,color:'#ff9c62',desc:'Wide scatter burst. Level 2 clearance.'},
+ {id:'heavy',name:'HEAVY',label:'Heavy payload',cost:220,unlock:3,count:2,radius:112,color:'#ff765c',desc:'A bigger arcade blast. Level 3 clearance.'},
+ {id:'atomic',name:'ATOMIC',label:'Atomic payload',cost:480,unlock:5,count:1,radius:190,color:'#ed83b4',desc:'Fictional, screen-filling arcade pulse. Level 5 clearance.'}
+];
+const state={mode:'menu',level:1,credits:0,hull:3,maxHull:3,score:0,owned:['standard'],weapon:'standard',inventory:3,targets:[],bombs:[],particles:[],enemyShots:[],scroll:0,planeY:0,keys:{},last:0,frame:0,flash:0,shake:0,runHits:0,runDrops:0,unlockedLevel:1,levelKills:0};
+let W=960,H=540,dpr=1,toastTimer=0;
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!state.planeY)state.planeY=H*.31}
+new ResizeObserver(resize).observe(canvas);resize();
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),fmt=n=>String(n).padStart(3,'0');
+function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1250)}
+function weapon(){return weapons.find(w=>w.id===state.weapon)||weapons[0]}
+function showScreen(html){card.innerHTML=html;screen.classList.remove('hidden')}
+function hideScreen(){screen.classList.add('hidden')}
+function menu(){state.mode='menu';showScreen(`<div class="menu-layout"><div><div class="eyebrow">✦ FLIGHT WING 07 &nbsp; / &nbsp; OPERATION DUSTLINE</div><h1>THE SKY IS<br>YOUR <i>RUNWAY.</i></h1><p class="lede">A side-scrolling arcade sortie. Fly low, line up your drop, and clear every marked target. The terrain gets tougher with every level.</p><div class="button-row"><button class="primary" id="startBtn">START SORTIE &nbsp; ↗</button><button class="secondary" id="howBtn">FLIGHT MANUAL</button></div><div class="fineprint">↑ / ↓ ADJUST ALTITUDE &nbsp; · &nbsp; SPACE RELEASES PAYLOAD &nbsp; · &nbsp; P PAUSES</div></div><div class="hangar-side"><div class="eyebrow">MISSION BRIEF</div><div class="upgrade-row"><span>OBJECTIVE<small>Clear every marked ground target</small></span><b>✳</b></div><div class="upgrade-row"><span>THREATS<small>Hostile flak increases by level</small></span><b style="color:var(--orange)">!</b></div><div class="upgrade-row"><span>LOADOUT<small>Upgrade payloads between sorties</small></span><b>↗</b></div></div></div>`);
+$('#startBtn').onclick=()=>beginLevel();$('#howBtn').onclick=manual;updateHud()}
+function manual(){showScreen(`<div class="eyebrow">FIELD MANUAL / FLIGHT SCHOOL</div><h1>FLY. LINE UP.<br><i>LET GO.</i></h1><p class="lede">Your plane advances automatically. Use ↑ / ↓ or W / S to change altitude; position the dotted sight over a ground target and press SPACE (or tap DROP BOMB). Each level adds more targets, tougher defenses, and faster flak.</p><p class="lede">Targets take one or more hits. You have three hull points. Earn credits by clearing a level and spend them in the hangar on wider blast payloads. Unlock the fictional Atomic arcade payload at level 5.</p><div class="button-row"><button class="primary" id="backBtn">GOT IT — FLY</button></div><div class="fineprint">ALL WEAPONS AND TARGETS ARE FICTIONAL, ABSTRACT ARCADE ELEMENTS.</div>`);$('#backBtn').onclick=()=>beginLevel()}
+function makeTargets(){const n=4+Math.min(state.level,6);state.targets=[];for(let i=0;i<n;i++){const gap=rand(W*.55,W*.9),x=W*.76+i*gap+state.scroll;const hp=1+Math.floor((state.level-1)/3)+(Math.random()<.3&&state.level>2?1:0);state.targets.push({x,y:H*.78,kind:i%4,hp,maxHp:hp,alive:true,size:rand(20,29),seed:Math.random()*10})}state.levelKills=0}
+function beginLevel(){state.mode='playing';state.scroll=0;state.bombs=[];state.particles=[];state.enemyShots=[];state.runHits=0;state.runDrops=0;state.flash=0;state.shake=0;state.inventory=weapon().count;state.planeY=H*.30;makeTargets();hideScreen();$('#missionTag').textContent='ACTIVE SORTIE';$('#missionName').textContent=missionName();$('#flightStatus').textContent='FLIGHT PATH LOCKED';updateHud();showToast('LEVEL '+String(state.level).padStart(2,'0')+' — CLEAR ALL MARKED TARGETS')}
+function missionName(){return ['Dustline','Dry River','Iron Mesa','Red Basin','Long Shadow','Nightfall','Final Approach'][Math.min(state.level-1,6)]||'Endless Frontier'}
+function updateHud(){const remaining=state.targets.filter(t=>t.alive).length;$('#levelStat').textContent=String(state.level).padStart(2,'0');$('#targetStat').textContent=state.mode==='menu'?'—':String(remaining).padStart(2,'0');$('#hullStat').textContent='♥'.repeat(Math.max(0,state.hull))+'♡'.repeat(Math.max(0,state.maxHull-state.hull));$('#creditStat').textContent=fmt(state.credits);$('#weaponName').textContent=weapon().label.toUpperCase();$('#weaponHint').textContent=state.inventory+' READY · '+(weapon().id==='atomic'?'ARCADE PULSE':'FREEFALL');}
+function showHangar(bonus){state.mode='hangar';const dots=Array.from({length:7},(_,i)=>`<span class="level-dot ${i<state.level?'done':i===state.level?'current':''}">${i+1}</span>`).join('');const opts=weapons.map(w=>{const owned=state.owned.includes(w.id),locked=state.level<w.unlock;return `<button class="weapon-option ${state.weapon===w.id?'selected':''}" data-weapon="${w.id}" ${!owned?'disabled':''}>${w.label}${owned?' ✓':locked?' · LV '+w.unlock:' · '+w.cost+' CR'}</button>`}).join('');const upgrades=[{id:'armor',name:'Reinforced hull',desc:`Hull ${state.maxHull}/4`,cost:170,done:state.maxHull>=4},{id:'repair',name:'Hull repair',desc:`Restore one point · ${state.hull}/${state.maxHull}`,cost:80,done:state.hull>=state.maxHull}];showScreen(`<div class="menu-layout"><div><div class="eyebrow">SORTIE COMPLETE &nbsp; / &nbsp; LEVEL ${String(state.level).padStart(2,'0')}</div><h1>${state.levelKills} TARGETS<br><i>NEUTRALIZED.</i></h1><p class="lede">Good flying. +${bonus} credits secured. Refit your loadout, then deploy to the next sector.</p><div class="eyebrow">SECTOR PROGRESS</div><div class="level-grid">${dots}</div><div class="eyebrow">SELECT PAYLOAD</div><div class="weapon-select">${opts}</div><div class="button-row"><button class="primary" id="nextBtn">${state.level===7?'NEXT FRONTIER':'DEPLOY LEVEL '+String(state.level+1).padStart(2,'0')} &nbsp; ↗</button></div></div><div class="hangar-side"><div class="eyebrow">HANGAR / ${fmt(state.credits)} CREDITS</div>${upgrades.map(u=>`<div class="upgrade-row"><span>${u.name}<small>${u.desc}</small></span><button class="buy" data-up="${u.id}" ${u.done||state.credits<u.cost?'disabled':''}>${u.done?'READY':u.cost+' CR'}</button></div>`).join('')}<div class="fineprint">NEXT PAYLOAD CLEARANCE: LEVEL 5</div></div></div>`);
+card.querySelectorAll('[data-weapon]').forEach(b=>b.onclick=()=>{state.weapon=b.dataset.weapon;updateHud();showHangar(0)});card.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>buyUpgrade(b.dataset.up));$('#nextBtn').onclick=()=>{state.level++;state.unlockedLevel=Math.max(state.unlockedLevel,state.level);if(state.hull===0)state.hull=1;beginLevel()};$('#missionTag').textContent='SECTOR CLEAR';$('#missionName').textContent='Return to hangar';$('#flightStatus').textContent='REFIT AVAILABLE';updateHud()}
+function buyUpgrade(id){if(id==='armor'&&state.maxHull<4&&state.credits>=170){state.credits-=170;state.maxHull++;state.hull++;showToast('HULL REINFORCED')}else if(id==='repair'&&state.hull<state.maxHull&&state.credits>=80){state.credits-=80;state.hull++;showToast('HULL REPAIRED')}else{const w=weapons.find(a=>a.id===id);if(w&&state.credits>=w.cost&&state.level>=w.unlock){state.credits-=w.cost;state.owned.push(w.id);state.weapon=w.id;showToast(w.label+' CLEARED')}}showHangar(0);updateHud()}

